aP6(a){return a+" \u0644\u0645 \u064a\u062d\u0642\u0642 \u0627\u0644\u0646\u062a\u0627\u0626\u062c \u0627\u0644\u062a\u064a \u0623\u0631\u0627\u062f\u0647\u0627 \u0641\u064a \u0627\u0644\u0623\u0633\u0627\u0628\u064a\u0639 \u0627\u0644\u0623\u062e\u064a\u0631\u0629."},
aP7(a){return a+" \u064a\u0645\u0631 \u0628\u0641\u062a\u0631\u0629 \u0645\u062a\u0642\u0644\u0628\u0629."},
gaPe(){return"\u0627\u0644\u0641\u0631\u064a\u0642\u0627\u0646 \u0645\u062a\u0642\u0627\u0631\u0628\u0627\u0646 \u062c\u062f\u0627\u064b \u0641\u064a \u062c\u062f\u0648\u0644 \u0627\u0644\u062a\u0631\u062a\u064a\u0628."},
gaPf(){return"\u0627\u0644\u0641\u0627\u0626\u0632 \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0645\u0628\u0627\u0631\u0627\u0629 \u0633\u064a\u062e\u0637\u0648 \u062e\u0637\u0648\u0629 \u0645\u0647\u0645\u0629 \u0641\u064a \u0627\u0644\u062a\u0631\u062a\u064a\u0628."},
